      pt: ["Inaugurado em 1979 como parque infantil estatal", "Destino popular para passeios familiares", "Oferece inúmeras atrações e áreas de lazer", "Ponto de encontro histórico para gerações de crianças"],
      fr: ["Ouvert en 1979 en tant que parc pour enfants de l'État", "Destination populaire pour les sorties en famille", "Propose de nombreux manèges et aires de jeux", "Lieu de rencontre historique pour des générations d'enfants"],
